/* ==UserStyle==
@name           Gemini Blurry Background (Arch Colors)
@namespace      github.com/openstyles/stylus
@version        1.2.0
@description    Gemini blurry color-mesh tweaked for Arch Linux
@author         coolpixels / Dude
==/UserStyle== */

@-moz-document url-prefix("https://gemini.google.com/")
{
  /* set background */
  body {
    background-image: linear-gradient(
        #1e293b50,
        #0f172a40,
        #090d1660,
        #090d16be,
        #05070b
      ),
      url("data:image/webp;base64,") !important;
    background-size: cover, cover !important;
    background-repeat: no-repeat, no-repeat !important;
    background-position: center center, center center !important;
    /* Hue-rotate shifts the warm orange/red blobs into cool Arch blue/purple/slate */
    backdrop-filter: blur(40px) brightness(0.28) hue-rotate(190deg) saturate(0.85) !important;
  }

  /* remove backgrounds from main components */
  chat-window,
  input-container,
  bard-sidenav,
  mat-sidenav-container {
    background: transparent !important;
  }

  /* style sidebar */
  bard-sidenav {
    border-right: 1px solid #89b4fa25 !important;
    backdrop-filter: blur(40px);
  }

  /* style gemini chat bubbles */
  .response-container {
    padding: 16px !important;
    background-color: #0b0f1945 !important;
    border: 2px solid #89b4fa20 !important;
    border-radius: 12px !important;
  }

  /* style user chat bubbles */
  .user-query-bubble-with-background {
    background-color: #0b0f1955 !important;
    border: 2px solid #89b4fa25 !important;
  }

  /* remove gradient by input container */
  input-container::before {
    all: unset !important;
  }
}

