/* ==========================================
   FROSTED GRAPHITE 2.0
   ChatGPT · Stylus
   ========================================== */

/* Google Font */
@import url('https://fonts.googleapis.com/css2?family=Coming+Soon&display=swap');

/* ---------- COLOR SYSTEM ---------- */

:root[data-theme="dark"] {
  color-scheme: dark;

  --app-color-background-surface: #191e28;
  --app-color-background-surface-under: #151a23;
  --app-color-background-elevated-primary: #222a37;
  --app-color-background-elevated-primary-opaque: #222a37;
  --app-color-background-elevated-secondary: #293343;
  --app-color-background-elevated-secondary-opaque: #293343;
  --app-color-background-elevated-tertiary-opaque: #303c4f;
  --app-color-background-control: #283243;
  --color-background-control-opaque: #283243;
  --color-background-panel: #1c2330;

  --app-color-background-accent: #263d5b;
  --app-color-background-accent-hover: #304d70;
  --app-color-background-accent-active: #354f73;

  --app-color-border: rgba(166, 190, 225, .13);
  --app-color-border-heavy: rgba(166, 190, 225, .23);
  --app-color-border-light: rgba(166, 190, 225, .08);
  --app-color-border-focus: #83b9ff;

  --app-color-text-foreground: #e3eaf5;
  --app-color-text-foreground-secondary: #aab8cc;
  --app-color-text-foreground-tertiary: #7f90a8;
  --app-color-text-accent: #9bc7ff;

  --app-color-icon-primary: #dce7f6;
  --app-color-icon-secondary: #aabbd1;
  --app-color-icon-tertiary: #8294ad;

  --color-background-user-message: #29394d;
  --color-text-user-message: #e9f1fc;
  --color-background-text-selection: #659de866;
}

/* ---------- TYPOGRAPHY ---------- */

html,
body,
button,
input,
textarea,
select,
[contenteditable="true"],
.prose,
.markdown,
[class*="text-"] {
  font-family: "Coming Soon", cursive !important;
}

/* Don't make code look handwritten */
pre,
code,
kbd,
samp,
.hljs,
.cm-editor,
.monaco-editor {
  font-family: "JetBrains Mono", monospace !important;
}

/* ---------- MAIN BACKGROUND ---------- */

html[data-theme="dark"] body {
  background: #191e28 !important;
}

/* ---------- SIDEBAR ---------- */

.sidebar-navigation {
  background:
    radial-gradient(ellipse at 15% 0%, #29394d 0%, transparent 48%),
    linear-gradient(160deg, #202a38 0%, #1b2330 50%, #191f2a 100%) !important;

  border-right: 1px solid rgba(153, 184, 225, .13);
}

/* Sidebar header */
.sidebar-navigation .header-LjJHnp {
  background: transparent !important;
}

/* Sidebar navigation controls */
.sidebar-navigation button {
  border-radius: 12px !important;
  transition: all .2s ease !important;
}

.sidebar-navigation button:hover {
  background: rgba(130, 177, 239, .10) !important;
  color: #dceaff !important;
}

/* Sidebar content rows */
.sidebar-navigation a,
.sidebar-navigation [role="button"] {
  border-radius: 11px !important;
  transition: all .2s ease !important;
}

.sidebar-navigation a:hover,
.sidebar-navigation [role="button"]:hover {
  background: rgba(130, 177, 239, .10) !important;
}

/* Selected sidebar item */
.sidebar-navigation [aria-current="page"],
.sidebar-navigation [data-active="true"] {
  background: linear-gradient(
    105deg,
    rgba(105, 164, 237, .20),
    rgba(153, 133, 255, .12)
  ) !important;

  border: 1px solid rgba(139, 184, 245, .18) !important;
  border-radius: 11px !important;
}

/* Sidebar profile area */
.sidebar-item {
  border-radius: 13px !important;
  transition: background .2s ease;
}

.sidebar-item:hover {
  background: rgba(130, 177, 239, .10) !important;
}

/* ---------- TOP BAR ---------- */

header {
  background: rgba(25, 31, 43, .88) !important;
  backdrop-filter: blur(18px) saturate(145%);
  -webkit-backdrop-filter: blur(18px) saturate(145%);
  border-bottom: 1px solid rgba(153, 184, 225, .12) !important;
}

/* Top bar buttons — restrained, not oversized */
header button {
  border-radius: 10px !important;
  transition: all .18s ease !important;
}

header button:hover {
  background: rgba(126, 174, 239, .12) !important;
  color: #b9d7ff !important;
}

/* Conversation title / model menu buttons */
header button[aria-haspopup="menu"] {
  background: linear-gradient(
    120deg,
    rgba(103, 156, 222, .15),
    rgba(153, 133, 255, .10)
  ) !important;

  border: 1px solid rgba(145, 187, 244, .20) !important;
  border-radius: 11px !important;
  padding: 6px 12px !important;
}

header button[aria-haspopup="menu"]:hover {
  background: rgba(116, 166, 235, .22) !important;
  border-color: rgba(145, 187, 244, .42) !important;
}

/* ---------- CHAT AREA ---------- */

.scrollContainer-fG6qEo {
  scrollbar-color: #52647e transparent;
}

/* User messages */
[data-message-author-role="user"] .whitespace-pre-wrap {
  background: linear-gradient(
    135deg,
    #2b3b50,
    #30364c
  );
  border: 1px solid rgba(145, 180, 230, .12);
  border-radius: 19px !important;
  padding: 11px 16px !important;
}

/* ---------- COMPOSER ---------- */

form,
[data-testid="composer"] {
  background: linear-gradient(
    145deg,
    rgba(39, 49, 66, .98),
    rgba(31, 40, 55, .98)
  ) !important;

  border: 1px solid rgba(145, 180, 230, .20) !important;
  border-radius: 23px !important;

  box-shadow:
    0 8px 30px rgba(0, 0, 0, .20),
    inset 0 1px 0 rgba(255, 255, 255, .025) !important;

  transition: border-color .2s ease, box-shadow .2s ease !important;
}

form:focus-within,
[data-testid="composer"]:focus-within {
  border-color: rgba(126, 180, 255, .48) !important;
  box-shadow: 0 0 0 3px rgba(100, 160, 240, .08) !important;
}

/* ---------- BUTTONS ---------- */

button {
  transition:
    background .18s ease,
    border-color .18s ease,
    color .18s ease !important;
}

button:focus-visible {
  outline: 2px solid #83b9ff !important;
  outline-offset: 3px;
}

/* ---------- LINKS ---------- */

a {
  color: #9bc7ff;
}

a:hover {
  color: #c2dcff;
}

/* ---------- SCROLLBARS ---------- */

* {
  scrollbar-width: thin;
  scrollbar-color: #45566f transparent;
}

::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}

::-webkit-scrollbar-thumb {
  background: #45566f;
  border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
  background: #7189aa;
}

/* ---------- SELECTION ---------- */

::selection {
  background: rgba(113, 169, 245, .32);
  color: #fff;
}



/* ==========================================
   TYPOGRAPHY + SIDEBAR FIX
   ========================================== */

/* Force Coming Soon throughout the interface */
:root,
body,
body *,
body *::before,
body *::after {
  font-family: "Coming Soon", cursive !important;
  font-weight: 600 !important;
  font-synthesis: weight !important;
}

/* Preserve icon fonts and code fonts */
svg,
svg *,
[class*="icon"],
[class*="Icon"],
[class*="lucide"],
pre,
pre *,
code,
code *,
kbd,
samp {
  font-family: initial !important;
}

/* Make the text slightly more readable */
body {
  -webkit-font-smoothing: antialiased;
}


/* ==========================================
   SIDEBAR — SINGLE ACTIVE CHAT HIGHLIGHT
   ========================================== */

/* Outer selected chat box */
.sidebar-navigation [aria-current="page"],
.sidebar-navigation [data-active="true"] {
  background: rgba(105, 145, 220, 0.25) !important;
  border: 1px solid rgba(145, 187, 244, 0.30) !important;
  border-radius: 13px !important;

  padding: 9px 12px !important;
  margin: 3px 0 !important;

  box-shadow: none !important;
}

/* Remove inner box backgrounds and borders */
.sidebar-navigation [aria-current="page"] *,
.sidebar-navigation [data-active="true"] * {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
}

/* Keep text visible */
.sidebar-navigation [aria-current="page"],
.sidebar-navigation [data-active="true"] {
  color: #dceaff !important;
}

/* ==========================================
   GLOBAL TYPOGRAPHY SCALE — 120%
   ========================================== */

html {
  font-size: 120% !important;
}

/* Chat messages */
[data-message-author-role],
.prose,
.markdown,
[class*="message-content"] {
  font-size: 1.2em !important;
  line-height: 1.75 !important;
}

/* Sidebar conversation titles */
.sidebar-navigation {
  font-size: 1.12em !important;
}

/* Composer text */
textarea,
[contenteditable="true"] {
  font-size: 1.15em !important;
  line-height: 1.6 !important;
}

/* Buttons and navigation */
button {
  font-size: 1.08em;
}

/* Make base chat text, lists, and code blocks thicker */
.markdown p,
.markdown li,
.markdown td,
.query-text,
message-content,
.model-response-text {
    font-weight: 600 !important; /* Change to 600 if you want it semi-bold */
}

/* Keep actual bold text distinctly heavier so it still pops */
.markdown strong,
.markdown b,
.markdown h1,
.markdown h2,
.markdown h3,
.markdown th {
    font-weight: 800 !important;
}

/* Optional: Thicken up the code blocks too */
.markdown pre,
.markdown code {
    font-weight: 600 !important;
}

html{
    font-weight: 800 !important;
}

@import url('https://fonts.googleapis.com/css2?family=Coming+Soon&display=swap');

/* === 1. COLOR PALETTE & FONT TOKENS === */
:root,
body {
  /* Custom Theme Variables (Unified Navy Center) */
  --bg-main: #1e2530;
  --bg-sidebar: #1b222c;
  --bg-elevated: #283344;
