  --text-muted: #8a9bb2;
  --accent-blue: #5c8ec6;
  --accent-blue-soft: #7aa7e0;

  /* Google Calendar & Tasks Material 3 (GM3) Overrides */
  --gm3-ref-typeface-brand: 'Coming Soon', cursive !important;
  --gm3-ref-typeface-plain: 'Coming Soon', cursive !important;

  --gm3-sys-color-background: var(--bg-main) !important;
  --gm3-sys-color-surface: var(--bg-main) !important;
  --gm3-sys-color-surface-dim: var(--bg-sidebar) !important;
  --gm3-sys-color-surface-bright: var(--bg-elevated) !important;
  --gm3-sys-color-surface-container-lowest: var(--bg-main) !important;
  --gm3-sys-color-surface-container-low: var(--bg-sidebar) !important;
  --gm3-sys-color-surface-container: var(--bg-sidebar) !important;
  --gm3-sys-color-surface-container-high: var(--bg-elevated) !important;
  --gm3-sys-color-surface-container-highest: #303d52 !important;

  --gm3-sys-color-on-background: var(--text-main) !important;
  --gm3-sys-color-on-surface: var(--text-main) !important;
  --gm3-sys-color-on-surface-variant: var(--text-muted) !important;

  --gm3-sys-color-outline: #405066 !important;
  --gm3-sys-color-outline-variant: var(--border-subtle) !important;

  --gm3-sys-color-primary: var(--accent-blue) !important;
  --gm3-sys-color-on-primary: #0f141b !important;
  --gm3-sys-color-primary-container: var(--bg-elevated) !important;
  --gm3-sys-color-on-primary-container: var(--accent-blue-soft) !important;

  --gm3-sys-color-secondary-container: var(--bg-elevated) !important;
  --gm3-sys-color-on-secondary-container: var(--text-main) !important;

  /* Legacy Token Fallbacks */
  --surface: var(--bg-main) !important;
  --on-surface: var(--text-main) !important;
  --on-surface-variant: var(--text-muted) !important;
  --hairline: var(--border-subtle) !important;
  --textfield-surface: var(--bg-input) !important;
  --fab: var(--bg-elevated) !important;
  --fab-hover: #324056 !important;
}

/* === 2. FORCE COMING SOON (BOLD) EVERYWHERE EXCEPT ICONS === */
*:not(.google-material-icons):not(.material-icons):not(.material-icons-extended):not(.material-symbols-outlined):not(.DPvwYc) {
  font-family: 'Coming Soon', cursive !important;
  font-weight: 700 !important;
  font-synthesis: weight !important;
  letter-spacing: 0.2px;
}

/* Protect Google's icon fonts */
.google-material-icons,
.material-icons,
.material-icons-extended,
.material-symbols-outlined,
.DPvwYc {
  font-family: 'Google Material Icons', 'Material Icons Extended', 'Material Icons', 'Material Symbols Outlined' !important;
  font-weight: 400 !important;
}

/* === 3. LAYOUT SURFACES & POLISH === */
html,
body {
  background-color: var(--bg-main) !important;
  color: var(--text-main) !important;
}

/* Top Header & Side Panels */
header[role="banner"],
[role="complementary"] {
  background-color: var(--bg-sidebar) !important;
  border-color: var(--border-subtle) !important;
}

/* Main Calendar Grid & Full-Page Tasks Center */
[role="main"],
main {
  background-color: var(--bg-main) !important;
}

/* Event Creation Popups, Modals & Dropdowns */
[role="dialog"],
[role="menu"],
[role="listbox"] {
  background-color: var(--bg-elevated) !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 16px !important;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45) !important;
}

/* Inputs & Search Bar */
input,
textarea {
  background-color: var(--bg-input) !important;
  color: var(--text-main) !important;
  border-radius: 12px !important;
}

/* Event Chips: softer pill look */
[data-eventchip] {
  border-radius: 10px !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25) !important;
  transition: transform 0.12s ease, filter 0.12s ease !important;
}

[data-eventchip]:hover {
  transform: translateY(-1px);
  filter: brightness(1.08);
}

/* Subtle Custom Scrollbar */
::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}

::-webkit-scrollbar-track {
  background: var(--bg-main);
}

::-webkit-scrollbar-thumb {
  background: var(--bg-elevated);
  border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--accent-blue);
}

